TempleSky.customGLSL:
// @node templeSky
// @title Temple Sky
// @category custom
// @description Golden-hour sky seen along a ray: teal zenith, amber horizon haze, a wide Mie halo and an HDR sun disc (disc = 0 hides the disc, e.g. for fog colour). Feed it camera rays for the background and reflected rays for mirrors.
vec3 templeSky(vec3 rd, vec3 sunDir, float disc) {
    rd = normalize(rd);
    vec3 s = normalize(sunDir);
    float y = rd.y;
    float mu = clamp(dot(rd, s), 0.0, 1.0);
    vec3 zenith = vec3(0.025, 0.11, 0.24);
    vec3 mid = vec3(0.30, 0.40, 0.47);
    // horizon is golden toward the sun and cools to teal-grey away from it
    float muH = dot(normalize(rd.xz + vec2(1e-5)), normalize(s.xz + vec2(1e-5))) * 0.5 + 0.5;
    vec3 horizon = mix(vec3(0.30, 0.44, 0.52), vec3(1.30, 0.62, 0.26), pow(clamp(muH, 0.0, 1.0), 2.5));
    float h = clamp(y, 0.0, 1.0);
    vec3 sky = mix(horizon, mid, smoothstep(0.0, 0.22, h));
    sky = mix(sky, zenith, smoothstep(0.12, 0.75, h));
    // warm dusty haze below the horizon
    sky = mix(sky, vec3(0.55, 0.30, 0.15), smoothstep(0.0, 0.25, -y));
    // Mie forward scattering around the sun
    sky += vec3(1.5, 0.80, 0.36) * pow(mu, 6.0) * 0.8;
    sky += vec3(1.2, 0.70, 0.35) * pow(mu, 48.0) * 1.6;
    // HDR sun disc
    sky += disc * vec3(40.0, 26.0, 14.0) * smoothstep(0.99955, 0.99975, mu);
    return sky;
}

GodRays.customGLSL:
// @node godRays
// @title God Rays
// @category effect
// @description Screen-space light shafts (radial blur toward the sun): marches from each pixel toward sunUV, accumulating the occlusion mask stored in the texture's alpha. density = how far toward the sun to sample (0..1), decay = falloff per sample.
float godRays(sampler2D tex, vec2 uv, vec2 sunUV, float density, float decay) {
    const int N = 56;
    vec2 delta = (uv - sunUV) * density / float(N);
    float jitter = fract(sin(dot(gl_FragCoord.xy, vec2(12.9898, 78.233))) * 43758.5453);
    vec2 c = uv - delta * jitter;
    float illum = 1.0;
    float acc = 0.0;
    float wsum = 0.0;
    for (int i = 0; i < N; i++) {
        c -= delta;
        acc += texture(tex, clamp(c, 0.001, 0.999)).a * illum;
        wsum += illum;
        illum *= decay;
    }
    return acc / wsum;
}

DirToScreen.customGLSL:
// @node dirToScreen
// @title Dir To Screen
// @category sdf3d
// @description Projects a world direction (e.g. the sun) into 0..1 screen coordinates for a camera given by position, target and fov (same convention as CameraObject / Raymarch).
vec2 dirToScreen(vec3 camPos, vec3 camTarget, float fov, vec3 dir) {
    vec3 ww = normalize(camTarget - camPos + vec3(0.0, 0.0, 1e-6));
    vec3 uu = normalize(cross(ww, vec3(0.0, 1.0, 0.0)));
    vec3 vv = cross(uu, ww);
    float f = 1.0 / tan(radians(clamp(fov, 1.0, 179.0)) * 0.5);
    vec3 d = normalize(dir);
    float z = max(dot(d, ww), 1e-3);
    vec2 p = vec2(dot(d, uu), dot(d, vv)) * f / z;
    float aspect = u_resolution.x / u_resolution.y;
    return vec2(p.x / aspect, p.y) * 0.5 + 0.5;
}

LensStreak.customGLSL:
// @node lensStreak
// @title Lens Streak
// @category effect
// @description Anamorphic lens streak: a wide horizontal Gaussian smear of only the hottest part of a glow texture (above threshold). width in UV units.
vec3 lensStreak(sampler2D tex, vec2 uv, float width, float threshold) {
    vec3 acc = vec3(0.0);
    float wsum = 0.0;
    for (int i = -24; i <= 24; i++) {
        float x = float(i) / 24.0;
        float w = exp(-abs(x) * 4.0);
        vec3 s = texture(tex, vec2(uv.x + x * width, uv.y)).rgb;
        acc += max(s - vec3(threshold), vec3(0.0)) * w;
        wsum += w;
    }
    return acc / wsum / max(1.0 - threshold, 0.05);
}
